mapper.select:
SELECT u.id, u.user_name, u.account_name, u.locked, u.account_type, u.create_user_id, u.description, u.create_time, u.account_port_type, u.chrid, u.org_id, o.org_name FROM t_sys_user u LEFT JOIN t_org_info o ON o.id = u.org_id
AND u.account_name LIKE CONCAT('%', #{accountName}, '%')
AND u.user_name LIKE CONCAT('%', #{userName}, '%')
AND u.locked = #{locked}
AND u.org_id = #{orgId}
ORDER BY u.id
